const stationLabels=['Radio','Signal Post','Decoder','Bridge','Relay','Switch','Gate','Marker','Terminal','Beacon'];
const missions=missionData.map((d,i)=>({id:i+1,region:Math.floor(i/10),index:i%10,type:d[0],title:d[1],answer:d[2],shift:d[3],story:d[4],lore:d[5],station:stationLabels[i%10]}));
function encodeMission(m){const p=m.answer;switch(m.type){case 'caesar':return cipher(p,m.shift);case 'atbash':return atbash(p);case 'a1z26':return encodeNum(p);case 'reverse':return reverse(p);case 'pigpen':return '[PIGPEN GLYPHS]';case 'morse':return encodeMorse(p);case 'binary':return encodeBinary(p);case 'rail':return encodeRail(p);case 'layer':return cipher(reverse(p),m.shift)}return p}
const milestones=[{n:1,name:'FIRST CONTACT',description:'Solve your first transmission.'},{n:5,name:'SIGNAL SCOUT',description:'Recover five transmissions.'},{n:10,name:'FOREST CODEBREAKER',description:'Finish Radio Woods.'},{n:15,name:'RUNE READER',description:'Recover fifteen transmissions.'},{n:20,name:'CANYON EXPLORER',description:'Finish Symbol Canyon.'},{n:25,name:'MASTER DECODER',description:'Recover twenty-five transmissions.'},{n:30,name:'GUARDIAN OF THE GUILD',description:'Restore the beacon.'}];
function loadSave(){let s={solved:[],hints:{},points:0,agent:'AGENT NOVA',region:0,sound:true,started:false,seenEnd:false};try{let v=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(v&&typeof v==='object'){s={...s,...v};s.solved=Array.isArray(v.solved)?[...new Set(v.solved.filter(n=>Number.isInteger(n)&&n>=1&&n<=30))]:[];s.hints=typeof v.hints==='object'&&v.hints&&!Array.isArray(v.hints)?v.hints:{};s.region=Math.min(2,Math.max(0,Number(v.region)||0));s.points=Math.max(0,Number(v.points)||0);s.agent=String(v.agent||'AGENT NOVA').slice(0,20)}}catch(e){/* Invalid saves use defaults. */}return s}
let save=loadSave();
const persist=()=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify(save))}catch(e){toast('Local saving is unavailable in this browser.') }};
const currentMission=()=>missions.find(m=>!save.solved.includes(m.id))||null;
const isUnlockedRegion=r=>r===0||save.solved.length>=r*10;
const currentRegionMissions=r=>missions.filter(m=>m.region===r);
const solvedInRegion=r=>currentRegionMissions(r).filter(m=>save.solved.includes(m.id)).length;
const isInteractable=m=>save.solved.includes(m.id)||m.id===(currentMission()?.id);
const badgeCount=()=>milestones.filter(m=>save.solved.length>=m.n).length;
let hero={x:68,y:299,walk:0},keys={},camera=0,nearby=null, lastFrame=0,particles=0,modalStack=[],toastTimeout=0;
let toolkit={type:'caesar',input:'',shift:3};
const canvas=$('#world'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const hash=n=>{let x=Math.sin(n*127.1+39.44)*43758.5453;return x-Math.floor(x)};
const locs=Array.from({length:10},(_,i)=>125+i*145);
const activeGlobalIndex=()=>currentMission()?.id||30;
function activeIndexForRegion(){const m=currentRegionMissions(save.region).find(m=>!save.solved.includes(m.id));return m?m.index:9}
function goToRegion(r,teleport=true){if(!isUnlockedRegion(r)){toast('Complete the previous region to unlock this area.');return}save.region=r;if(teleport){const idx=activeIndexForRegion();hero.x=Math.max(45,locs[idx]-55);hero.y=299;camera=Math.max(0,Math.min(WORLD_WIDTH-W,hero.x-W*.39))}persist();updateUI();if(modalStack.length)closeAllModals();toast('Entered '+regions[r].name)}
function trackObjective(){const idx=activeIndexForRegion();hero.x=Math.max(45,locs[idx]-48);hero.y=299;camera=Math.max(0,Math.min(WORLD_WIDTH-W,hero.x-W*.38));toast('Signal located. Press E or click its console.');canvas.focus({preventScroll:true})}
function updateUI(){const r=save.region,reg=regions[r],cm=currentMission(),regional=currentRegionMissions(r),open=regional.find(m=>!save.solved.includes(m.id)),display=open||regional[9],count=solvedInRegion(r);$('#regionName').textContent=reg.label;$('#chapterMeta').textContent=`CHAPTER ${pad(r+1)} / 03`;$('#topStatus').textContent=save.solved.length===30?'ALL CHANNELS RESTORED':'ENCRYPTED CHANNEL ACTIVE';$('#agentName').textContent=save.agent;$('#agentRank').textContent=save.solved.length>=20?'SENIOR CODEBREAKER':save.solved.length>=10?'FIELD OPERATIVE':'ROOKIE CODEBREAKER';$('#statSolved').textContent=pad(save.solved.length);$('#statScore').textContent=pad(save.points,4);$('#statBadges').textContent=pad(badgeCount());$('#missionCount').textContent=`${pad(display.id)} / 30`;$('#missionId').textContent=open?`MISSION ${pad(display.id)} · INCOMING`:`CHAPTER ${pad(r+1)} · COMPLETE`;$('#missionTitle').textContent=open?display.title:'Region Secured';$('#missionSummary').textContent=open?display.story:reg.finish;$('#missionType').textContent=open?cipherInfo[display.type].name:'ALL SIGNALS DECODED';$('#btnMission').querySelector('span').textContent=open?'DECODE TRANSMISSION':(cm?'NEXT CHAPTER':'MISSION COMPLETE');$('#regionFraction').textContent=`${count}/10`;$('#progressRegion').textContent=reg.name;$('#progressPct').textContent=`${count*10}%`;$('#progressFill').style.width=`${count*10}%`;$('#regionMessage').textContent=count===10?'All transmissions recovered in this region.':'Decode transmissions to unlock the route ahead.';$('#screenObjective').textContent=open?`Find ${display.station.toLowerCase()} ${display.index+1}: ${display.title}`:'All transmissions secured · region complete';$('#screenWeather').textContent=r===0?'FREQ // 87.3 MHz':r===1?'RUNES // ARCHIVED':'ENGINE // ONLINE';$('#btnSound').textContent=save.sound?'♪':'♪̸';$('#nodeList').innerHTML=regional.map(m=>`<button type="button" class="${save.solved.includes(m.id)?'solved':(open&&open.id===m.id?'current':'')}" data-action="mission-node" data-id="${m.id}" title="${esc(m.title)} ${save.solved.includes(m.id)?'(solved)':(open&&open.id===m.id?'(active)':'(locked)')}" aria-label="Mission ${m.id}: ${esc(m.title)}">${save.solved.includes(m.id)?'✓':m.index+1}</button>`).join('');$('#storyTicker').textContent=save.solved.length===30?'The beacon is restored. The Cipher Guild is connected again.':save.solved.length?missions.filter(m=>save.solved.includes(m.id)).at(-1).lore:'Every secret has a pattern. Every pattern has a key.'}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3200)}
function audioTone(freq=440,duration=.085,shape='square'){if(!save.sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const ac=audioTone.ac||(audioTone.ac=new Audio());if(ac.state==='suspended')ac.resume();const osc=ac.createOscillator(),gain=ac.createGain();osc.type=shape;osc.frequency.setValueAtTime(freq,ac.currentTime);gain.gain.setValueAtTime(.035,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);osc.connect(gain);gain.connect(ac.destination);osc.start();osc.stop(ac.currentTime+duration)}catch(e){}}
function sfx(type){if(type==='good'){audioTone(523,.10);setTimeout(()=>audioTone(659,.09),100);setTimeout(()=>audioTone(784,.18),190)}else if(type==='bad')audioTone(190,.12,'sawtooth');else audioTone(610,.06)}
function modOpen(view,opts={}){modalStack.push({view,opts});renderModal()}
function modalReplace(view,opts={}){modalStack=[{view,opts}];renderModal()}
function modalBack(){if(!modalStack.length)return;modalStack.pop();renderModal();if(!modalStack.length)canvas.focus({preventScroll:true})}
function closeAllModals(){modalStack=[];renderModal();canvas.focus({preventScroll:true})}
function modalFrame(title,kicker,body,footer='',size=''){return `<div class="modal-backdrop" data-backdrop><section class="modal-window ${size}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-heading"><div><div class="modal-kicker">${esc(kicker)}</div><h2>${esc(title)}</h2></div><button class="close-btn" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`}
const btn=(name,act,cl='plain-btn',attrs='')=>`<button type="button" class="${cl}" data-action="${act}" ${attrs}>${name}</button>`;
function renderModal(){const root=$('#modalRoot');if(!modalStack.length){root.innerHTML='';return}const {view,opts}=modalStack.at(-1);let html='';if(view==='intro')html=renderIntro();if(view==='mission')html=renderMission(opts.id);if(view==='toolkit')html=renderToolkit();if(view==='map')html=renderMap();if(view==='guide')html=renderGuide();if(view==='journal')html=renderJournal();if(view==='settings')html=renderSettings();if(view==='chapter')html=renderChapter(opts.region);if(view==='ending')html=renderEnding();root.innerHTML=html;const auto=$('[autofocus]',root);if(auto)auto.focus({preventScroll:true});else $('.close-btn',root)?.focus({preventScroll:true})}
function renderIntro(){return modalFrame('Welcome, Codebreaker','CIPHER GUILD // TOP SECRET',`<div class="story-tag">★ CHAPTER 01 // OPERATION QUIET SIGNAL</div><h1 class="hero-headline">THE WORLD HAS<br>GONE <span class="mint-text">SILENT.</span></h1><p class="story-copy">The Guild's communication network is fading. Strange messages have appeared at an abandoned radio tower, and a mysterious sender called <strong class="accent-text">ECHO</strong> has been blamed. Your assignment: investigate, decode the broadcasts, and uncover what really happened.</p><div class="intro-grid"><div class="intro-step"><b>01</b><strong>EXPLORE</strong><p>Move with A/D or arrow keys. Click a console or press E when close.</p></div><div class="intro-step"><b>02</b><strong>DECODE</strong><p>Use cipher tools, the handbook, and hints to crack transmissions.</p></div><div class="intro-step"><b>03</b><strong>UNLOCK</strong><p>Solve thirty missions, restore three regions, and reveal the truth.</p></div></div><p class="tagline">PROGRESS SAVES ON THIS BROWSER · NO STUDENT LOGIN REQUIRED</p>`,btn('VIEW FIELD GUIDE','guide','plain-btn')+btn(save.started?'RESUME OPERATION →':'ACCEPT MISSION →','start','action-btn'),'wide')}
function pigpenGlyph(letter){const k=letter.charCodeAt(0)-65;if(k<0||k>25)return '';let p='',dot=false;if(k<18){const i=k%9,row=Math.floor(i/3),col=i%3;dot=k>=9;let lines=[];if(row>0)lines.push('M 7 6 H 25');if(row<2)lines.push('M 7 26 H 25');if(col>0)lines.push('M 7 6 V 26');if(col<2)lines.push('M 25 6 V 26');p=lines.map(c=>`<path d="${c}"/>`).join('');}else{const i=(k-18)%4;dot=k>=22;const edge=[['M 5 4 L 16 16 L 27 4'],['M 28 5 L 16 16 L 28 27'],['M 5 28 L 16 16 L 27 28'],['M 4 5 L 16 16 L 4 27']];p=`<path d="${edge[i][0]}"/>`;}return `<svg viewBox="0 0 32 32" aria-label="${letter}" role="img" xmlns="http://www.w3.org/2000/svg"><g fill="none" stroke="#f4d08d" stroke-width="2.6" stroke-linejoin="miter" stroke-linecap="square">${p}</g>${dot?'<circle cx="16" cy="16" r="2.1" fill="#5ae5c4"/>':''}</svg>`}
function pigpenEncoded(t){return `<div class="glyph-encoded" role="img" aria-label="Pigpen cipher message; use glyph chart to decode">${[...t].map(c=>c===' '?'<span class="glyph-space"></span>':`<span class="glyph-unit">${pigpenGlyph(c)}</span>`).join('')}</div>`}
function hintText(m,index){const base={caesar:[`Use the Caesar wheel. The message was shifted forward by ${m.shift}; decode by moving backward.`,`Set the tool to shift ${m.shift} and enter the intercepted text.`,`The first word begins with ${m.answer.split(' ')[0].slice(0,2)} and has ${m.answer.split(' ')[0].length} letters.`],atbash:['Reverse the alphabet: A ↔ Z, B ↔ Y, and so on.','The Atbash tool translates the intercepted letters for you.',`The first word has ${m.answer.split(' ')[0].length} letters and starts with ${m.answer[0]}.`],a1z26:['Numbers match alphabet positions: A=1, B=2, … Z=26.','Separate number groups at hyphens; each slash separates words.',`The first decoded word starts with ${m.answer[0]}.`],reverse:['Try reading the entire encoded text from the last character to the first.','The reverse-text tool can flip the entire transmission.',`The first word is ${m.answer.split(' ')[0].length} letters long.`],pigpen:['Open the Pigpen tab. Every glyph matches one letter in its chart.','Grid fragments A–I have no dot; J–R have dots. X fragments S–V have no dot; W–Z have dots.',`The decoded message starts with the letter ${m.answer[0]}.`],morse:['Dots are short signals and dashes are long signals. Each space separates a letter.','Open the Morse receiver and paste the transmission to decode it.',`The decoded first word begins with ${m.answer[0]}.`],binary:['Each group of 8 zeroes and ones is an ASCII character. 01000001 is A.','Use the binary terminal to convert 8-bit groups to letters.',`The first word starts with ${m.answer[0]}.`],rail:['The encoded text was written on two alternating rows.','Try the 2-rail decoder to interleave the two rows.',`The decoded message begins with ${m.answer.split(' ')[0].slice(0,2)}.`],layer:[`The message was first reversed and then shifted forward ${m.shift}. Undo the Caesar shift first.`,`Select Two-stage decoder, shift ${m.shift}, then reverse the result.`,`The original message starts with ${m.answer[0]}.`]};return base[m.type][index]}
function renderMission(id){const m=missions[id-1];if(!m)return '';const solved=save.solved.includes(id),unlocked=isInteractable(m);if(!unlocked)return modalFrame('Transmission Locked','ACCESS DENIED',`<p class="story-copy">Complete the current assignment before accessing this transmission.</p>`,btn('BACK','close'),'narrow');const hintN=Math.min(3,Number(save.hints[id]||0)),enc=encodeMission(m);const ciphertext=m.type==='pigpen'?pigpenEncoded(m.answer):esc(enc);let footer=btn('OPEN DECODER TOOLKIT ◉','toolkit-from-mission','plain-btn',`data-id="${m.id}"`)+btn(solved?'CLOSE REPLAY':'SUBMIT DECODE →',solved?'close':'submit','action-btn',solved?'':`data-id="${m.id}"`);return modalFrame(m.title,`TRANSMISSION ${pad(m.id)} // ${regions[m.region].subtitle.toUpperCase()}`,`<div class="puzzle-layout"><div><p class="puzzle-story">${esc(m.story)}</p><div class="signal-box"><div class="signal-top"><span>● INTERCEPTED TRANSMISSION</span><span>${cipherInfo[m.type].name}</span></div><div class="cipher-text">${ciphertext}</div></div>${solved?`<div class="complete-banner" style="margin-top:16px"><strong>✓ TRANSMISSION DECODED</strong><p>${esc(m.lore)}</p><span class="accent-text">ANSWER: ${esc(m.answer)}</span></div>`:`<label for="decodeAnswer" class="input-label">YOUR DECODED MESSAGE</label><input class="answer-input" id="decodeAnswer" type="text" maxlength="100" placeholder="ENTER YOUR ANSWER HERE" autocomplete="off" spellcheck="false" autofocus><div id="answerFeedback" class="error-msg" aria-live="polite"></div>`}</div><aside class="mission-support"><div class="support-label">✦ FIELD INTELLIGENCE</div><p>${esc(cipherInfo[m.type].guide)}</p><div class="support-label">HINTS / ${hintN} OF 3</div><ul class="hint-list">${Array.from({length:hintN},(_,i)=>`<li>HINT ${i+1}: ${esc(hintText(m,i))}</li>`).join('')}</ul>${!solved&&hintN<3?btn('REVEAL NEXT HINT (−15 PTS)','hint','outline-btn hint-btn',`data-id="${m.id}"`):''}<p class="small-caption">${solved?'Replay mode · No additional points.':'Full mission value: 100 points. Hints reduce the points earned, not your progress.'}</p></aside></div>`,footer,'wide')}
function renderToolkit(){const types=['caesar','atbash','a1z26','reverse','pigpen','morse','binary','rail','layer'],type=toolkit.type,info=cipherInfo[type],m=currentMission();return modalFrame('Cipher Toolkit','FIELD EQUIPMENT // DECODER WORKBENCH',`<div class="tool-tabs">${types.map(t=>`<button type="button" class="tab-btn ${type===t?'active':''}" data-action="tool-tab" data-tool="${t}">${cipherInfo[t].label}</button>`).join('')}</div><div class="tool-body"><div><p class="story-copy">${esc(info.guide)}</p>${type==='pigpen'?`<p class="support-label">GLYPH REFERENCE · A TO Z</p><div class="glyph-ref">${[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(c=>`<div class="reference-cell"><b>${c}</b>${pigpenGlyph(c)}</div>`).join('')}</div><p class="small-caption">Read each symbol in your mission and match it to its letter in this chart.</p>`:`<label class="input-label" for="toolInput">INTERCEPTED TEXT / YOUR INPUT</label><textarea class="tool-input" rows="3" id="toolInput" spellcheck="false">${esc(toolkit.input)}</textarea>${type==='caesar'||type==='layer'?`<div class="shift-controls"><button data-action="shift-down" aria-label="Decrease shift">−</button><div class="shift-value" id="shiftReadout">SHIFT ${toolkit.shift}</div><button data-action="shift-up" aria-label="Increase shift">+</button></div>`:''}<label class="input-label">DECODED OUTPUT</label><div class="tool-readout" id="toolOutput">${esc(toolResult())}</div>${m&&m.type===type?btn('LOAD CURRENT TRANSMISSION','load-transmission','outline-btn',`style="margin-top:11px"`):''}`}</div><aside><div class="support-label">HOW IT WORKS</div><p class="tool-note">${esc(info.guide)}</p><div class="support-label" style="margin-top:18px">EXAMPLE</div><p class="tool-note">${esc(info.example)}</p>${type==='morse'?`<div class="reference-grid">${Object.entries(MORSE_TABLE).map(([k,v])=>`<div class="reference-cell"><b>${k}</b><span>${v}</span></div>`).join('')}</div>`:''}${type==='a1z26'?`<div class="reference-grid">${[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map((c,i)=>`<div class="reference-cell"><b>${c}</b><span>${i+1}</span></div>`).join('')}</div>`:''}<p class="small-caption">These are learning tools. Use them freely while decoding. They never automatically submit an answer.</p></aside></div>`,btn('BACK TO MISSION','close','plain-btn')+btn('FIELD GUIDE','guide','action-btn'),'wide')}
function toolResult(){const {type,input,shift}=toolkit;if(!input.trim())return 'AWAITING INPUT…';switch(type){case 'caesar':return cipher(input,-shift);case 'atbash':return atbash(input);case 'a1z26':return decodeNum(input);case 'reverse':return reverse(input);case 'morse':return decodeMorse(input);case 'binary':return decodeBinary(input);case 'rail':return decodeRail(input);case 'layer':return reverse(cipher(input,-shift));default:return 'CONSULT GLYPH CHART'}}
function renderMap(){return modalFrame('World Map','CIPHER GUILD // SECTOR ACCESS',`<p class="story-copy">Travel to unlocked regions. Each has ten stations to investigate. Your progress is saved even when you revisit earlier areas.</p><div class="map-cards">${regions.map((r,i)=>{const unlocked=isUnlockedRegion(i),count=solvedInRegion(i);return `<button type="button" class="map-card ${i===save.region?'active-region':''}" data-action="region" data-region="${i}" ${unlocked?'':'disabled'}><div class="map-art ${i===1?'desert':i===2?'archive':''}"><span class="map-sigil">${r.symbol}</span></div><div class="map-info"><span class="map-num">REGION ${pad(i+1)} // ${count}/10 TRANSMISSIONS</span><strong>${esc(r.name)}</strong><p>${esc(r.tag)}</p><span class="map-open">${unlocked?(i===save.region?'● CURRENT REGION':'↗ TRAVEL TO REGION'):'🔒 COMPLETE PRIOR CHAPTER'}</span></div></button>`}).join('')}</div>`,btn('RETURN TO FIELD','close'),'wide')}
function renderGuide(){return modalFrame('Codebreaker’s Handbook','TRAINING MANUAL // ALL CLEARANCE LEVELS',`<p class="story-copy">A field reference for every encryption method in Cipher Quest. The first chapters introduce familiar substitution patterns; the Archives add signals, binary representation, and multi-step decoding.</p>${Object.entries(cipherInfo).map(([id,info])=>`<div class="guide-entry"><h3>${esc(info.name)}</h3><p>${esc(info.guide)}</p><div class="guide-example">${esc(info.example)}</div>${id==='pigpen'?`<div class="glyph-ref" style="margin-top:12px">${[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(c=>`<div class="reference-cell"><b>${c}</b>${pigpenGlyph(c)}</div>`).join('')}</div>`:''}</div>`).join('')}`,btn('BACK','close')+btn('OPEN TOOLKIT','toolkit','action-btn'),'wide')}
function renderJournal(){const solved=missions.filter(m=>save.solved.includes(m.id));return modalFrame('Case Journal','CLASSIFIED RECORD // AUTOMATICALLY UPDATED',`<p class="story-copy">Your mission record is saved locally. ${solved.length?`You have recovered ${solved.length} transmissions so far.`:'Your first transmission is still waiting to be decoded.'}</p><div class="support-label" style="margin-bottom:13px">ACHIEVEMENTS</div><div class="badge-row">${milestones.map(b=>`<div class="badge-item ${save.solved.length>=b.n?'':'locked'}"><strong>${save.solved.length>=b.n?'★':'◇'} ${esc(b.name)}</strong><small>${esc(b.description)}</small></div>`).join('')}</div><div class="support-label" style="margin:19px 0 12px">RECOVERED INTELLIGENCE</div>${solved.length?solved.map(m=>`<div class="journal-entry"><b>✓ ${pad(m.id)} · ${esc(m.title)}</b><p>“${esc(m.answer)}” — ${esc(m.lore)}</p></div>`).join(''):'<p class="muted-text">No solved transmissions yet. Return to the forest radio to begin.</p>'}`,btn('RETURN TO FIELD','close'),'wide')}
function renderSettings(){return modalFrame('Settings & Progress','AGENT OPTIONS // LOCAL STORAGE',`<label class="input-label" for="agentCallsign">AGENT CALLSIGN (NOT YOUR REAL NAME)</label><input id="agentCallsign" class="answer-input" type="text" maxlength="20" value="${esc(save.agent)}" placeholder="AGENT NOVA"><p class="small-caption">Use a nickname. This app does not need student names or accounts.</p><div class="settings-row"><div><strong>RETRO SOUND EFFECTS</strong><p>Short, optional synthesized feedback sounds.</p></div><input type="checkbox" id="soundToggle" ${save.sound?'checked':''} aria-label="Sound effects"></div><div class="settings-row"><div><strong>RESET GAME PROGRESS</strong><p>Deletes the save for this browser only. This cannot be undone.</p></div><button data-action="reset-confirm" class="danger-btn">RESET</button></div><div class="settings-row"><div><strong>OFFLINE & PRIVACY</strong><p>Progress is stored in this browser's localStorage. No accounts, tracking, or network connections.</p></div><span class="mint-text">LOCAL</span></div>`,btn('SAVE SETTINGS','save-settings','action-btn'),'narrow')}
function renderChapter(r){const next=r+1;return modalFrame('Chapter Secured!',`REGION ${pad(r+1)} // SIGNALS RESTORED`,`<div class="story-tag">★ ALL TEN TRANSMISSIONS DECODED</div><h1 class="hero-headline">${esc(regions[r].name.toUpperCase())}<br><span class="mint-text">COMPLETE.</span></h1><p class="story-copy">${esc(regions[r].finish)}</p><p class="story-copy">Your investigation continues. The next region introduces new cipher techniques and more difficult clues.</p>`,btn('REVISIT REGION','close')+(next<3?btn('TRAVEL TO NEXT REGION →','chapter-next','action-btn',`data-region="${next}"`):btn('VIEW FINAL REPORT →','ending','action-btn')),'narrow')}
function renderEnding(){return modalFrame('Operation Complete','CIPHER GUILD // FINAL DEBRIEF',`<div class="story-tag">★ MASTER CODEBREAKER UNLOCKED</div><h1 class="hero-headline">THE SIGNAL<br><span class="mint-text">IS RESTORED.</span></h1><p class="story-copy">Thirty messages. Three regions. One truth: <strong>ECHO was protecting the Cipher Guild all along.</strong> A corrupted relay had disguised its warnings as threats. By recognizing patterns and undoing layer after layer of encryption, you restored the network and cleared ECHO's name.</p><div class="complete-banner"><b>★ ALL 30 MISSIONS COMPLETE</b><p>You can return to any sector, replay puzzles, and use the cipher tools anytime.</p></div><div class="reward-stat">${pad(save.points,4)} <span class="small-caption">TOTAL POINTS</span></div>`,btn('OPEN CASE JOURNAL','journal')+btn('RETURN TO WORLD →','close','action-btn'),'narrow')}
function startMission(id){const m=missions[id-1];if(!m){toast('Transmission unavailable.');return}if(!isInteractable(m)){toast('That station is locked. Decode the earlier transmission first.');sfx('bad');return}sfx('tap');modOpen('mission',{id})}
function solveMission(id){const m=missions[id-1],input=$('#decodeAnswer'),feedback=$('#answerFeedback');if(!m||!input||!feedback)return;const guess=normalize(input.value);if(!guess){feedback.textContent='Enter your decoded message before submitting.';return}if(guess!==normalize(m.answer)){feedback.textContent='Not quite. Recheck the code, adjust your decoder, or reveal a hint.';sfx('bad');input.select();return}if(save.solved.includes(id)){toast('Transmission already decoded.');return}if(currentMission()?.id!==id){toast('Complete transmissions in order.');return}const hints=Math.min(3,Number(save.hints[id]||0)),awarded=Math.max(55,100-15*hints);save.points+=awarded;save.solved.push(id);persist();updateUI();sfx('good');toast(`SIGNAL DECODED · +${awarded} POINTS`);if(id%10===0){modalReplace(id===30?'ending':'chapter',{region:m.region});return}modalReplace('success',{id,awarded});renderModal()}
function renderSuccess(id,awarded){const m=missions[id-1];return modalFrame('Signal Decoded!',`MISSION ${pad(id)} // TRANSMISSION RECOVERED`,`<div class="complete-banner"><b>✓ CORRECT DECODE: ${esc(m.answer)}</b><p>${esc(m.lore)}</p></div><div class="reward-stat">+${awarded} <span class="small-caption">POINTS EARNED</span></div><p class="story-copy" style="margin-top:14px">The next station has unlocked. Follow the glowing waypoint or use <strong>Track Signal</strong> to jump there.</p>`,btn('RETURN TO FIELD','close','plain-btn')+btn('TRACK NEXT SIGNAL →','success-next','action-btn'),'narrow')}
const _renderModal=renderModal;
renderModal=function(){const root=$('#modalRoot');if(!modalStack.length){root.innerHTML='';return}const {view,opts}=modalStack.at(-1);if(view==='success'){root.innerHTML=renderSuccess(opts.id,opts.awarded);$('.close-btn',root)?.focus({preventScroll:true});return}_renderModal()};
function openToolkit(id){const m=id?missions[id-1]:currentMission();toolkit.type=m?cipherInfo[m.type].tool:toolkit.type;toolkit.shift=m?.shift||3;toolkit.input=m&&m.type!=='pigpen'?encodeMission(m):'';modOpen('toolkit')}
function openNav(view){modOpen(view)}
function actionClick(e){const el=e.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;const id=Number(el.dataset.id||0);switch(act){case 'close':modalBack();break;case 'start':save.started=true;persist();closeAllModals();canvas.focus({preventScroll:true});toast('Mission accepted. Follow the golden beacon.');break;case 'mission-node':startMission(id);break;case 'submit':solveMission(id);break;case 'hint':{const n=Math.min(3,Number(save.hints[id]||0));if(n>=3)return;save.hints[id]=n+1;persist();renderModal();$('#decodeAnswer')?.focus({preventScroll:true});sfx('tap');break}case 'toolkit-from-mission':openToolkit(id);break;case 'toolkit':openToolkit();break;case 'guide':openNav('guide');break;case 'journal':openNav('journal');break;case 'map':openNav('map');break;case 'settings':openNav('settings');break;case 'tool-tab':toolkit.type=el.dataset.tool;renderModal();break;case 'shift-down':toolkit.shift=(toolkit.shift+25)%26;refreshTool();sfx('tap');break;case 'shift-up':toolkit.shift=(toolkit.shift+1)%26;refreshTool();sfx('tap');break;case 'load-transmission':{const m=currentMission();if(m&&m.type!=='pigpen'){toolkit.input=encodeMission(m);$('#toolInput').value=toolkit.input;refreshTool();toast('Current transmission loaded.')}break}case 'region':goToRegion(Number(el.dataset.region));break;case 'chapter-next':goToRegion(Number(el.dataset.region));break;case 'ending':modalReplace('ending');break;case 'success-next':closeAllModals();const cm=currentMission();if(cm&&cm.region!==save.region){goToRegion(cm.region)}else trackObjective();break;case 'save-settings':{const v=$('#agentCallsign')?.value||'';save.agent=v.toUpperCase().replace(/[^A-Z0-9 -]/g,'').trim().slice(0,20)||'AGENT NOVA';save.sound=Boolean($('#soundToggle')?.checked);persist();updateUI();modalBack();toast('Settings saved locally.');break}case 'reset-confirm':if(window.confirm('Reset all 30 mission saves, points, hints, and agent progress on this browser?')){const sound=save.sound;try{localStorage.removeItem(SAVE_KEY)}catch(e){}save=loadSave();save.sound=sound;hero.x=68;hero.y=299;camera=0;persist();updateUI();modalReplace('intro');toast('New game ready.')}break}}
function refreshTool(){const el=$('#toolOutput');if(el)el.textContent=toolResult();const sh=$('#shiftReadout');if(sh)sh.textContent=`SHIFT ${toolkit.shift}`}
document.addEventListener('click',actionClick);
document.addEventListener('input',e=>{if(e.target.id==='toolInput'){toolkit.input=e.target.value;refreshTool()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='decodeAnswer'){e.preventDefault();const m=modalStack.at(-1);if(m?.view==='mission')solveMission(m.opts.id)}});
document.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]'))modalBack()});
$('#btnGuide').addEventListener('click',()=>openNav('guide'));
$('#btnHandbook').addEventListener('click',()=>openNav('guide'));
$('#btnSettings').addEventListener('click',()=>openNav('settings'));
$('#btnMap').addEventListener('click',()=>openNav('map'));
$('#btnRegions').addEventListener('click',()=>openNav('map'));
$('#btnJournal').addEventListener('click',()=>openNav('journal'));
$('#btnToolkit').addEventListener('click',()=>openToolkit());
$('#brandHome').addEventListener('click',()=>openNav('intro'));
$('#btnMission').addEventListener('click',()=>{const m=currentRegionMissions(save.region).find(m=>!save.solved.includes(m.id));if(m)startMission(m.id);else if(save.solved.length===30)openNav('ending');else goToRegion(save.region+1)});
$('#btnJump').addEventListener('click',trackObjective);
$('#btnSound').addEventListener('click',()=>{save.sound=!save.sound;persist();updateUI();if(save.sound)sfx('tap');toast(save.sound?'Audio on':'Audio off')});
$('#btnFullscreen').addEventListener('click',()=>{const el=$('#viewport');if(document.fullscreenElement){document.exitFullscreen?.()}else{el.requestFullscreen?.().catch(()=>toast('Full-screen mode is unavailable.'))}});
const blocked=()=>modalStack.length>0;
function interact(){if(blocked())return;const m=nearby;if(m&&isInteractable(m)){startMission(m.id);return}if(m&&!isInteractable(m)){toast('Locked. Complete the earlier station.');sfx('bad');return}const open=currentRegionMissions(save.region).find(m=>!save.solved.includes(m.id));if(!open){if(save.solved.length===30)openNav('ending');else openNav('map');return}toast('Approach a glowing station, or select TRACK SIGNAL to find it.');sfx('bad')}
const movementKeys=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','a','d','w','s','A','D','W','S'];
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(blocked()){e.preventDefault();modalBack()}return}const typing=e.target.matches('input,textarea,[contenteditable]');if(typing||blocked())return;if(movementKeys.includes(e.key)){keys[e.key.toLowerCase()]=true;if(e.key.startsWith('Arrow'))e.preventDefault()}if(e.key.toLowerCase()==='e'){e.preventDefault();if(!e.repeat)interact()}});
window.addEventListener('keyup',e=>{delete keys[e.key.toLowerCase()]});
window.addEventListener('blur',()=>keys={});
for(const [id,key] of [['moveLeft','arrowleft'],['moveRight','arrowright']]){const b=$('#'+id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[key]=true});for(const eventName of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(eventName,()=>delete keys[key])}
$('#moveAction').addEventListener('click',interact);
canvas.addEventListener('pointerdown',e=>{if(blocked())return;const bounds=canvas.getBoundingClientRect(),x=(e.clientX-bounds.left)/bounds.width*W+camera;let nearest=missions.filter(m=>m.region===save.region).map(m=>({m,d:Math.abs(x-locs[m.index])})).sort((a,b)=>a.d-b.d)[0];if(nearest&&nearest.d<43){hero.x=Math.max(45,locs[nearest.m.index]-42);if(isInteractable(nearest.m))startMission(nearest.m.id);else toast('Transmission locked. Decode earlier stations first.')}else canvas.focus({preventScroll:true})});

// Pixel-art renderer. All artwork is drawn in code; no network image dependencies.
const fill=(x,y,w,h,col)=>{ctx.fillStyle=col;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))};
function poly(pts,color){ctx.fillStyle=color;ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}
function line(x1,y1,x2,y2,c,w=2){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function pixelSky(r,t){const palettes=[['#132238','#172a43','#223850','#314a60','#4b5869','#856875'],['#382b4d','#5f405c','#975666','#bf796c','#dda17a','#e1b888'],['#101a2b','#192b3e','#223449','#29445a','#365266','#3e6071']];const colors=palettes[r];colors.forEach((c,i)=>fill(0,i*48,640,49,c));for(let i=0;i<65;i++){const x=hash(i*23+8)*640,y=hash(i*32+19)*210,tw=hash(i*6+1)>.75?2:1;if(r!==1||i%4===0)fill(x,y,tw,tw,hash(i*19)>.65?'#b0bfd0':'#607c9d')}if(r===0){ellipse(512,65,29,29,'#d2c49a');ellipse(519,60,25,25,'#e8d5a6');fill(0,205,640,10,'#3d5069')}else if(r===1){ellipse(485,88,46,46,'#f4bc83');fill(0,204,640,18,'#c78a71')}else{ellipse(495,84,36,36,'#426780');ellipse(491,82,30,30,'#537c8b')}
}
function drawMountainLayer(offset,r){const shift=camera*.14;ctx.save();ctx.translate(-shift,0);for(let x=-150;x<1500;x+=200){const c=r===1?'#87565e':r===0?'#2b4558':'#263b4c';poly([[x,223],[x+90,123+(hash(x)*35)],[x+200,223]],c);if(r===0)poly([[x+78,162],[x+90,126+(hash(x)*35)],[x+113,160]],'#8c9496')}ctx.restore()}
function spruce(x,y,size,c){const cx=x-camera*.36;fill(cx-3,y-19*size,6,30*size,'#333f3b');for(let k=0;k<3;k++)poly([[cx,y-(72-k*17)*size],[cx-(24-k*3)*size,y-(24+k*8)*size],[cx+(24-k*3)*size,y-(24+k*8)*size]],c)}
function farForest(t){for(let i=0;i<38;i++){const x=i*42+hash(i)*16-80;spruce(x,272,.62+hash(i*13)*.5,i%3?'#223e45':'#2c4b50')}fill(0,282,640,20,'#2c4742')}
function drawDesertFar(){ctx.save();ctx.translate(-camera*.3,0);for(let i=0;i<10;i++){const x=-200+i*180;fill(x,190,110,80,'#905d61');fill(x+14,169,85,23,'#a56863');fill(x+31,153,53,20,'#b67a6c');fill(x+42,141,32,14,'#b67a6c');fill(x+8,210,95,7,'#7d5363')}ctx.restore();poly([[0,267],[145,242],[300,270],[470,253],[640,273],[640,304],[0,304]],'#b78674')}
function drawArchiveFar(t){fill(0,205,640,90,'#253649');for(let i=0;i<18;i++){const x=i*43-(camera*.16%43);fill(x,105,28,183,'#34465b');fill(x+4,110,20,149,'#18283b');fill(x+9,117,10,123,'#26485a');fill(x+12,120,4,112,'#4b9188');fill(x,188,33,7,'#45556a')}for(let i=0;i<8;i++){let x=i*95+20-camera*.12,y=62+(i%2)*45;drawGear(x,y,15,t*(i%2?1:-1),false)}fill(0,245,640,40,'#304358')}
function drawGear(x,y,rad,angle,solid=true){ctx.save();ctx.translate(x,y);ctx.rotate(angle);const color=solid?'#a88a63':'#4c6276';for(let i=0;i<8;i++){ctx.rotate(Math.PI/4);fill(-4,-rad-5,8,10,color)}ellipse(0,0,rad,rad,color);ellipse(0,0,rad*.55,rad*.55,solid?'#5d5c5b':'#26394c');ellipse(0,0,rad*.23,rad*.23,'#1b2537');ctx.restore()}
function forestProps(t){for(let i=0;i<20;i++){const x=i*87-32;const sx=x-camera;const size=.7+hash(i*5)*.6;if(sx<-95||sx>W+90)continue;fill(sx-3,219,7,78,'#39493f');for(let k=0;k<4;k++)poly([[sx,172-k*13],[sx-24*size,227-k*9],[sx+25*size,227-k*9]],i%3?'#2d5755':'#386a5b');fill(sx+5,274,3,5,'#64916e');if(i%4===0){fill(sx+35,289,5,5,'#e1a165');fill(sx+32,287,11,3,'#f1bb75')}}}
function desertProps(t){for(let i=0;i<14;i++){const x=i*130-45,sx=x-camera;if(sx<-40||sx>W+50)continue;fill(sx,265,9,32,'#456f6b');fill(sx-7,276,7,8,'#456f6b');fill(sx-7,267,4,11,'#456f6b');fill(sx+9,271,7,8,'#456f6b');fill(sx+12,263,4,12,'#456f6b');fill(sx-4,293,17,4,'#6e7168');if(i%3===1){fill(sx+30,274,19,20,'#94675c');fill(sx+31,268,17,7,'#be8870')}}}
function archiveProps(t){for(let i=0;i<15;i++){const x=i*115+37,sx=x-camera;if(sx<-90||sx>W+90)continue;fill(sx-7,219,34,77,'#3b4b58');fill(sx-2,219,23,57,'#263b4d');fill(sx+3,234,12,23,'#1d2d3a');if(i%3===0)drawGear(sx+12,261,11,t*(i%2?-1:1),true);else {fill(sx+5,244,8,5,'#e3b66e');fill(sx+8,249,2,29,'#79949b')}}}
function drawGround(r){const ground=['#324a43','#9b7765','#303c4d'][r],rim=['#5b7b64','#dcc094','#738294'][r];fill(0,296,640,64,ground);fill(0,293,640,5,rim);fill(0,302,640,2,['#436057','#b58f70','#3b5966'][r]);for(let i=0;i<120;i++){let sx=(i*47+hash(i*71)*30-camera*.83)%720;if(sx<0)sx+=720;const y=304+(hash(i*23)*45)|0;fill(sx,y,2+(i%3)*2,1+(i%2),r===1?'#b49172':r===2?'#46576b':'#537067')}if(r===0)for(let i=0;i<45;i++){const x=(i*61+hash(i)*33-camera)%W;fill((x+W)%W,290,2,4,i%2?'#75a073':'#91a879')}if(r===2)for(let i=0;i<7;i++){const sx=((i*120-camera)%750+750)%750;fill(sx,313,65,3,'#516276');fill(sx+15,303,7,34,'#495d71')}}
function drawTower(t){if(save.region!==0)return;const x=1513-camera;if(x>W+80||x<-100)return;fill(x-14,143,28,150,'#415463');fill(x-21,277,42,16,'#303c44');fill(x-23,211,45,8,'#5f686b');fill(x-16,165,30,11,'#89908d');fill(x-2,104,4,40,'#9ea59a');for(let i=0;i<4;i++){fill(x-17,183+i*23,34,3,'#647578');line(x-14,185+i*23,x+12,208+i*23,'#4b666a',2)}ellipse(x,106,5+Math.sin(t*3)*2,5+Math.sin(t*3)*2,'#6fe4c8')}
function drawStation(m,t){const x=locs[m.index]-camera;if(x<-60||x>W+60)return;const solved=save.solved.includes(m.id),active=currentMission()?.id===m.id,accessible=isInteractable(m);const highlight=active?'#f1d28e':solved?'#6de6c7':'#64778d';const y=286;ellipse(x,y+7,30,6,'#192731');if(active){const glow=Math.sin(t*3)*3;ellipse(x,y-28,30+glow,35+glow,'#edc98320');fill(x-27,y-65,54,2,'#8c7c59')}if(m.index%5===0){fill(x-20,y-42,40,44,'#405161');fill(x-15,y-36,30,23,'#142d3a');fill(x-11,y-32,22,15,active?'#2e8b82':'#366a76');fill(x-7,y-28,14,2,'#a8e7d4');fill(x-12,y-6,24,5,'#786e59');fill(x-25,y,50,5,'#768188')}else if(m.index%5===1){fill(x-15,y-61,30,63,'#58616c');fill(x-9,y-56,18,32,'#1a3541');fill(x-5,y-52,10,17,'#51968c');fill(x-2,y-79,4,18,'#7e8990');fill(x-12,y-3,24,7,'#8d897b')}else if(m.index%5===2){fill(x-20,y-36,40,37,'#6c6565');fill(x-16,y-32,32,23,'#223b48');fill(x-11,y-27,22,15,'#3a8d87');fill(x-3,y-25,7,4,'#c9d4a4');fill(x-25,y,50,6,'#82756a')}else if(m.index%5===3){fill(x-10,y-59,20,61,'#555a63');fill(x-18,y-59,36,10,'#968878');fill(x-12,y-33,24,14,'#283946');fill(x-5,y-29,10,6,'#71bcb3');fill(x-18,y,36,5,'#867e76')}else {fill(x-17,y-21,34,21,'#6d6257');fill(x-13,y-38,26,21,'#977d62');fill(x-8,y-33,16,11,'#f0bf74');fill(x-18,y,37,5,'#ac8c6b')}
 fill(x-22,y+5,44,4,'#29384c');if(!accessible&&!solved){fill(x-7,y-15,14,11,'#253246');fill(x-4,y-19,8,9,'#253246')}if(solved){fill(x-9,y-60,18,17,'#285c57');fill(x-5,y-54,11,3,'#8ff2c7');fill(x-6,y-55,4,6,'#8ff2c7')}else if(active){const bob=Math.sin(t*4)*3;poly([[x-8,y-85+bob],[x+8,y-85+bob],[x,y-75+bob]],'#ffcb7c');fill(x-2,y-105+bob,4,14,'#ffd28b')}fill(x-20,y+13,40,15,'#101b2a');fill(x-19,y+14,38,13,accessible?'#314857':'#202b3b');ctx.font='bold 9px monospace';ctx.fillStyle=highlight;ctx.textAlign='center';ctx.fillText(pad(m.index+1)+' '+(solved?'OK':active?'!':'—'),x,y+24)
}
function drawHero(t){const x=Math.round(hero.x-camera),y=Math.round(hero.y),moving=!!(keys.arrowleft||keys.arrowright||keys.a||keys.d||keys.w||keys.s||keys.arrowup||keys.arrowdown),bounce=moving?Math.sin(hero.walk)*2|0:0;ellipse(x,y+3,15,4,'#16262d');let foot=y-1+bounce;fill(x-13,foot-7,10,7,'#151e31');fill(x+3,foot-7,10,7,'#151e31');fill(x-9,foot-19,8,14,'#53677a');fill(x+1,foot-19,8,14,'#53677a');fill(x-11,foot-35,22,19,'#43556b');fill(x-17,foot-33,6,14,'#efbf94');fill(x+11,foot-33,6,14,'#efbf94');fill(x-9,foot-37,18,5,'#e8b87d');fill(x-8,foot-55,16,18,'#edbc91');fill(x-10,foot-61,20,8,'#263c56');fill(x-12,foot-57,25,5,'#f0c574');fill(x-9,foot-65,18,5,'#36506b');fill(x-5,foot-48,3,4,'#253343');fill(x+4,foot-48,3,4,'#253343');fill(x-2,foot-42,5,2,'#a97662');fill(x+7,foot-29,5,8,'#61dcca');fill(x+9,foot-27,2,4,'#d9ffff')}
function drawForeground(r,t){if(r===0){for(let i=0;i<27;i++){let x=((i*91-camera*1.15)%850+850)%850;fill(x,299+hash(i)*41,3,4,hash(i)>.5?'#6e9870':'#406d55')}}else if(r===1){for(let i=0;i<15;i++){let x=((i*73-camera*.9)%800+800)%800;fill(x,314+hash(i)*25,7,3,'#d0a07b')}}else{for(let i=0;i<8;i++){let x=((i*117-camera)%750+750)%750;fill(x,315,2,26,'#98a080')}}}
function drawParticles(t){const r=save.region;for(let i=0;i<26;i++){const x=(hash(i*13+1)*720+Math.sin(t*(.3+hash(i))*1.4+i)*15)%640,y=65+hash(i*33+5)*230+(Math.sin(t*.7+i)*10);const glow=(Math.sin(t*3+i*5)+1)*.5;fill(x,y,r===1?2:2,r===1?2:2,r===0?(glow>.6?'#b6cf83':'#5c9987'):r===1?'#f2d19c':'#62a8a3')}}
function drawRadar(t){const m=currentMission();if(!m||m.region!==save.region)return;const sx=locs[m.index]-camera;if(sx>W-30){fill(W-19,181,3,22,'#ffd18b');poly([[W-25,193],[W-17,186],[W-17,200]],'#ffd18b')}else if(sx<30){fill(19,181,3,22,'#ffd18b');poly([[25,193],[17,186],[17,200]],'#ffd18b')}}
function renderWorld(t){ctx.clearRect(0,0,W,H);const r=save.region;pixelSky(r,t);drawMountainLayer(0,r);if(r===0){farForest(t);forestProps(t)}else if(r===1){drawDesertFar();desertProps(t)}else{drawArchiveFar(t);archiveProps(t)}drawGround(r);if(r===0)drawTower(t);for(const m of currentRegionMissions(r))drawStation(m,t);drawHero(t);drawForeground(r,t);drawParticles(t);drawRadar(t)}
function frame(now){const dt=Math.min((now-lastFrame)/1000||.016,.06);lastFrame=now;const t=now/1000;let vx=0,vy=0;if(!blocked()){if(keys.arrowleft||keys.a)vx-=1;if(keys.arrowright||keys.d)vx+=1;if(keys.arrowup||keys.w)vy-=1;if(keys.arrowdown||keys.s)vy+=1}if(vx||vy){const norm=Math.hypot(vx,vy)||1;hero.x=Math.max(28,Math.min(WORLD_WIDTH-45,hero.x+vx/norm*172*dt));hero.y=Math.max(281,Math.min(316,hero.y+vy/norm*100*dt));hero.walk+=dt*19}const targetCam=Math.max(0,Math.min(WORLD_WIDTH-W,hero.x-218));camera+=(targetCam-camera)*Math.min(1,dt*8);nearby=currentRegionMissions(save.region).find(m=>Math.abs(hero.x-locs[m.index])<58)||null;const tip=$('#interactTip');if(!blocked()&&nearby){tip.hidden=false;tip.textContent=isInteractable(nearby)?`[ E ] ${save.solved.includes(nearby.id)?'REPLAY':'DECODE'} · ${nearby.title.toUpperCase()}`:'[ LOCKED ] COMPLETE EARLIER SIGNALS'}else tip.hidden=true;$('#coordinates').textContent=`SECTOR ${pad(save.region+1)} · ${pad(Math.round(hero.x),4)}`;renderWorld(t);requestAnimationFrame(frame)}
// Sanity checks for mission encodings and decoder pairs in development/browser console.
function validateMissions(){const problems=[];for(const m of missions){const encoded=encodeMission(m);let decoded='';switch(m.type){case 'caesar':decoded=cipher(encoded,-m.shift);break;case 'atbash':decoded=atbash(encoded);break;case 'a1z26':decoded=decodeNum(encoded);break;case 'reverse':decoded=reverse(encoded);break;case 'morse':decoded=decodeMorse(encoded);break;case 'binary':decoded=decodeBinary(encoded);break;case 'rail':decoded=decodeRail(encoded);break;case 'layer':decoded=reverse(cipher(encoded,-m.shift));break;case 'pigpen':decoded=m.answer}if(normalize(decoded)!==normalize(m.answer))problems.push({mission:m.id,decoded,answer:m.answer})}if(problems.length)console.error('Cipher Quest mission validation problems',problems);return problems}
window.CipherQuestTests={validateMissions,missions,encodeMission,decodeRail,encodeRail,encodeBinary,decodeBinary,encodeMorse,decodeMorse,encodeNum,decodeNum,cipher,pigpenGlyph,normalize,reset:()=>localStorage.removeItem(SAVE_KEY)};
updateUI();if(!save.started){modOpen('intro')}else if(save.solved.length===30&&!save.seenEnd){save.seenEnd=true;persist();modOpen('ending')}
validateMissions();requestAnimationFrame(frame);
